struct ThreadHistoryBuilder {
    turns: Vec<Turn>,
    current_turn: Option<Turn>,
    next_turn_index: usize,
    next_item_index: usize,
}

impl ThreadHistoryBuilder {
    fn new() -> Self {
        Self {
            turns: Vec::new(),
            current_turn: None,
            next_turn_index: 1,
            next_item_index: 1,
        }
    }

    fn finish(mut self) -> Vec<Turn> {
        self.finish_current_turn();
        self.turns
    }

    fn finish_current_turn(&mut self) {
        if let Some(mut turn) = self.current_turn.take() {
            turn.id = self.next_turn_index.to_string();
            self.turns.push(turn);
            self.next_turn_index += 1;
            self.next_item_index = 1;
        }
    }

    fn handle_user_message(&mut self, payload: &UserMessageEvent) {
        if self.current_turn.is_none() {
            self.current_turn = Some(Turn {
                id: self.next_turn_index.to_string(),
                items: Vec::new(),
                status: TurnStatus::InProgress,
                error: None,
            });
        }
        self.current_turn.as_mut().unwrap().items.push(ThreadItem {
            id: self.next_item_index.to_string(),
            content: payload.content.clone(),
            role: ThreadItemRole::User,
        });
        self.next_item_index += 1;
    }

    fn handle_agent_message(&mut self, message: String) {
        if self.current_turn.is_none() {
            self.current_turn = Some(Turn {
                id: self.next_turn_index.to_string(),
                items: Vec::new(),
                status: TurnStatus::InProgress,
                error: None,
            });
        }
        self.current_turn.as_mut().unwrap().items.push(ThreadItem {
            id: self.next_item_index.to_string(),
            content: message,
            role: ThreadItemRole::Agent,
        });
        self.next_item_index += 1;
    }

    fn handle_agent_reasoning(&mut self, payload: &AgentReasoningEvent) {
        if self.current_turn.is_none() {
            self.current_turn = Some(Turn {
                id: self.next_turn_index.to_string(),
                items: Vec::new(),
                status: TurnStatus::InProgress,
                error: None,
            });
        }
        self.current_turn.as_mut().unwrap().items.push(ThreadItem {
            id: self.next_item_index.to_string(),
            content: payload.content.clone(),
            role: ThreadItemRole::Agent,
        });
