    fn new() -> Self {
        Self {
            turns: Vec::new(),
            current_turn: None,
            next_turn_index: 1,
            next_item_index: 1,
        }
    }

    fn finish(mut self) -> Vec<Turn> {
        self.finish_current_turn();
        self.turns
    }

    fn finish_current_turn(&mut self) {
        if let Some(mut turn) = self.current_turn.take() {
            turn.id = self.next_turn_index.to_string();
            self.next_turn_index += 1;
            self.turns.push(turn);
        }
    }

    fn handle_user_message(&mut self, payload: &UserMessageEvent) {
        if let Some(turn) = self.current_turn.as_mut() {
            turn.items.push(ThreadItem {
                id: self.next_item_index.to_string(),
                user_input: Some(UserInput::Message(payload.clone())),
                agent_message: None,
            });
            self.next_item_index += 1;
        }
    }

    fn handle_agent_message(&mut self, message: String) {
        if let Some(turn) = self.current_turn.as_mut() {
            turn.items.push(ThreadItem {
                id: self.next_item_index.to_string(),
                user_input: None,
                agent_message: Some(message),
            });
            self.next_item_index += 1;
        }
    }

    fn handle_agent_reasoning(&mut self, payload: &AgentReasoningEvent) {
        self.handle_agent_message(payload.content.clone());
    }

    fn handle_agent_reasoning_raw_content(&mut self, payload: &AgentReasoningRawContentEvent) {
        self.handle_agent_message(payload.content.clone());
    }

    fn handle_thread_rollback(&mut self, payload: &ThreadRolledBackEvent) {
        self.finish_current_turn();
        self.next_turn_index = payload.new_start_index;
    }

    fn handle_turn_aborted(&mut self, payload: &TurnAbortedEvent) {
        if let Some(turn) = self.current_turn.as_mut() {
            turn.status = TurnStatus::Aborted(payload.reason.clone());
            turn.error = Some(TurnError {
                message: payload.message.clone(),
                code: payload.code.clone(),
            });
        }
    }
}

