    next_turn_index: usize,
    next_item_index: usize,
}

impl ThreadHistoryBuilder {
    fn new() -> Self {
        Self {
            turns: Vec::new(),
            current_turn: None,
            next_turn_index: 1,
            next_item_index: 1,
        }
    }

    fn finish(mut self) -> Vec<Turn> {
        self.finish_current_turn();
        self.turns
    }

    fn finish_current_turn(&mut self) {
        if let Some(mut turn) = self.current_turn.take() {
            turn.id = format!("turn-{}", self.next_turn_index);
            self.next_turn_index += 1;
            self.turns.push(turn);
        }
    }

    fn handle_user_message(&mut self, payload: &UserMessageEvent) {
        if self.current_turn.is_none() {
            self.current_turn = Some(Turn {
                id: format!("turn-{}", self.next_turn_index),
                items: Vec::new(),
                status: TurnStatus::InProgress,
                error: None,
            });
            self.next_turn_index += 1;
        }
        let turn = self.current_turn.as_mut().unwrap();
        turn.items.push(ThreadItem {
            id: format!("item-{}", self.next_item_index),
            content: payload.content.clone(),
            role: ThreadItemRole::User,
        });
        self.next_item_index += 1;
    }

    fn handle_agent_message(&mut self, message: String) {
        let turn = self.current_turn.as_mut().unwrap();
        turn.items.push(ThreadItem {
            id: format!("item-{}", self.next_item_index),
            content: message,
            role: ThreadItemRole::Assistant,
        });
        self.next_item_index += 1;
    }

    fn handle_agent_reasoning(&mut self, payload: &AgentReasoningEvent) {
        let turn = self.current_turn.as_mut().unwrap();
        turn.items.push(ThreadItem {
            id: format!("item-{}", self.next_item_index),
            content: payload.content.clone(),
            role: ThreadItemRole::Assistant,
        });
        self.next_item_index += 1;
    }

    fn handle_agent_reasoning_raw_content(&mut self, payload: &AgentReasoningRawContentEvent) {
        let turn = self.current_turn.as_mut().unwrap();
        turn.items.push(ThreadItem {
            id: format!("item-{}", self.next_item_index),
            content: payload.content.clone(),
            role: ThreadItemRole::Assistant,
        });
        self.next_item_index += 1;
    }

    fn handle_thread_rollback(&mut self, payload: &ThreadRolledBackEvent) {
        if let Some(turn) = self.turns.last_mut() {
            turn.items.truncate(payload.rollback_to);
            self.next_item_index = payload.rollback_to;
        }
    }

    fn handle_turn_aborted(&mut self, payload: &TurnAbortedEvent) {
        if let Some(turn) = self.current_turn.take() {
            let mut turn = Turn {
                id: turn.id,
                items: turn.items,
                status: TurnStatus::Aborted,
                error: Some(TurnError {
                    reason: payload.reason.clone(),
                }),
            };
            self.turns.push(turn);
        }
    }
}

