            content.into_iter().map(|block| {
                match block {
                    McpContentBlock::Text(text) => UserInput::Text(TextContent { text }),
                    McpContentBlock::Image(image) => UserInput::Image(image.path),
                    _ => UserInput::Text(TextContent { text: "Unsupported content type".to_string() }),
                }
            }).collect(),
            content,
            structured_content,
        },
        None => vec![],
    };

    let status = match end_event.status {
        McpToolCallStatus::Completed => ThreadItem::McpToolCall {
            id: end_event.id,
            server: end_event.server,
            tool: end_event.tool,
            status: McpToolCallStatus::Completed,
            arguments: end_event.arguments,
            result: Some(end_event.result.unwrap()),
            error: end_event.error,
            duration_ms: end_event.duration_ms,
        },
        McpToolCallStatus::Failed => ThreadItem::McpToolCall {
            id: end_event.id,
            server: end_event.server,
            tool: end_event.tool,
            status: McpToolCallStatus::Failed,
            arguments: end_event.arguments,
            result: end_event.result,
            error: Some(end_event.error.unwrap()),
            duration_ms: end_event.duration_ms,
        },
        _ => ThreadItem::McpToolCall {
            id: end_event.id,
            server: end_event.server,
            tool: end_event.tool,
            status: McpToolCallStatus::InProgress,
            arguments: end_event.arguments,
            result: end_event.result,
            error: end_event.error,
            duration_ms: end_event.duration_ms,
        },
    };

    ItemCompletedNotification {
        item: status,
        thread_id,
        turn_id,
    }
}
