    fn resolve_paths_in_value(value: &TomlValue, base_dir: &Path) -> io::Result<TomlValue> {
        match value {
            TomlValue::Table(table) => {
                let mut new_table = toml::map::Map::new();
                for (key, val) in table {
                    let resolved_val = resolve_paths_in_value(val, base_dir)?;
                    new_table.insert(key.clone(), resolved_val);
                }
                Ok(TomlValue::Table(new_table))
            }
            TomlValue::Array(array) => {
                let mut new_array = Vec::new();
                for item in array {
                    let resolved_item = resolve_paths_in_value(item, base_dir)?;
                    new_array.push(resolved_item);
                }
                Ok(TomlValue::Array(new_array))
            }
            TomlValue::String(s) => {
                if let Ok(mut path_buf) = s.parse::<std::path::PathBuf>() {
                    path_buf = base_dir.join(path_buf);
                    Ok(TomlValue::String(path_buf.to_string_lossy().to_string()))
                } else {
                    Ok(value.clone())
                }
            }
            _ => Ok(value.clone()),
        }
    }

    resolve_paths_in_value(&value_from_config_toml, base_dir)
}

