                            path,
                            head,
                            created_at,
                            updated_at,
                        });
                    }
                }
            }
        }
    }

    let reached_scan_cap = scanned_files >= MAX_SCAN_FILES;
    if reached_scan_cap && !items.is_empty() {
        more_matches_available = true;
    }

    let next = if more_matches_available {
