fn apply_transcript_selection(&self, area: Rect, buf: &mut Buffer) {
    let TRANSCRIPT_GUTTER_COLS = 2;
    let transcript_view_top = self.transcript_view_top;
    let transcript_total_lines = self.transcript_total_lines;

    if let Some(selection) = self.transcript_selection.current_selection() {
        let start_line = selection.start.line.saturating_sub(transcript_view_top);
        let end_line = selection.end.line.saturating_sub(transcript_view_top);
        let start_col = selection.start.col.saturating_sub(TRANSCRIPT_GUTTER_COLS);
        let end_col = selection.end.col.saturating_sub(TRANSCRIPT_GUTTER_COLS);

        if start_line < transcript_total_lines && end_line < transcript_total_lines {
            for line in start_line..=end_line {
                let line_content = buf.get_line(line).unwrap_or_default();
                let mut styled_line = line_content.clone();

                if line == start_line && line == end_line {
                    styled_line[start_col..end_col].stylize(style::Style::default().bg(color::Yellow));
                } else if line == start_line {
                    styled_line[start_col..].stylize(style::Style::default().bg(color::Yellow));
                } else if line == end_line {
                    styled_line[..end_col].stylize(style::Style::default().bg(color::Yellow));
                } else {
                    styled_line.stylize(style::Style::default().bg(color::Yellow));
                }

                buf.set_line(line, styled_line);
            }
        }
    }
}
