                        .map(|s| Span {
                            style: Style::default(),
                            content: std::borrow::Cow::Owned(s.to_string()),
                        })
                        .collect(),
                });
                joiner_before.push(Some(current_indent.content.clone()));

                current_line = String::new();
                current_indent = subsequent_indent.clone();
            }

            if !remaining_text.is_empty() {
                current_line.push_str(&current_indent.content);
                current_line.push_str(&remaining_text);
            }
        }
    }

    if !current_line.is_empty() {
        lines.push(Line {
            style: Style::default(),
            alignment: Alignment::Left,
            spans: current_line.split('\n')
                .map(|s| Span {
                    style: Style::default(),
                    content: std::borrow::Cow::Owned(s.to_string()),
                })
                .collect(),
        });
        joiner_before.push(Some(current_indent.content.clone()));
    }

    TranscriptLinesWithJoiners {
        lines,
        joiner_before,
    }
