            TerminalName::Ghostty => 3,
            TerminalName::Iterm2 => 1,
            TerminalName::VsCode => 1,
            TerminalName::Kitty => 3,
            _ => DEFAULT_EVENTS_PER_TICK,
        };

        if let Some(override_value) = overrides.events_per_tick {
            events_per_tick = override_value.max(1);
        }

